<?php
declare(strict_types=1);require dirname(__DIR__,2).'/bootstrap.php';use App\Core\Auth;use App\Core\Database;use App\Services\McpOAuthService;
$client=(string)($_GET['client_id']??$_POST['client_id']??'');$redirect=(string)($_GET['redirect_uri']??$_POST['redirect_uri']??'');$state=(string)($_GET['state']??$_POST['state']??'');$scope=(string)($_GET['scope']??$_POST['scope']??'bdc.events.read bdc.events.stage');$challenge=(string)($_GET['code_challenge']??$_POST['code_challenge']??'');$method=(string)($_GET['code_challenge_method']??$_POST['code_challenge_method']??'');$valid=McpOAuthService::client(Database::connection(),$client,$redirect);
