if(!Auth::isSuperAdmin()){http_response_code(401);?><!doctype html><meta charset="utf-8"><title>BDC authorization</title><p>Sign in to the BDC Portal as Super Admin, then return to ChatGPT and connect again.</p><p><a href="<?=e(url('login'))?>">Open BDC login</a></p><?php exit;}
